import { QLoading } from '@/components/loading/Loading';
import { createVNode, render, type VNode } from 'vue';

let instance: VNode | null = null;
let container: HTMLDivElement | null = null; // 👈 新增

export const useShowLoading = {
  /**
   * 显示加载
   * @param delay 延迟显示，单位毫秒
   */
  show(delay: number = 5000) {
    // 避免重复创建
    if (container) return;

    container = document.createElement('div');
    container.id = 'loading-container';
    container.style.position = 'fixed';
    container.style.top = '0';
    container.style.left = '0';
    container.style.width = '100%';
    container.style.height = '100%';
    container.style.zIndex = '9999';
    document.body.appendChild(container);

    const vnode = createVNode(QLoading, {
      type: 'skeleton',
    });

    render(vnode, container);
    instance = vnode;
    setTimeout(() => {
      this.hide();
    }, delay);
  },

  hide() {
    if (instance && container) {
      render(null, container); // 卸载 vnode
      document.body.removeChild(container); //

      // 清理引用
      instance = null;
      container = null;
    }
  },
};

useTimeDisplay.useTimeDisplay.ts:
// composables/useTimeDisplay.ts
import { ref } from 'vue';

import { handleDateFormat, UseTimeUtils } from '@qianrenni/core';

// 配置选项
export interface UseTimeDisplayOptions {
  autoStart?: boolean; // 是否自动启动，默认 true
  interval?: number; // 更新间隔，默认 1000ms
  onFinish?: () => void; // 倒计时结束回调
  mode?: 'countdown' | 'realtime'; // 模式控制
}

/**
 * Vue 3 Composable：统一的时间显示工具
 * 支持三种模式：
 *  - 倒计时（目标时间在未来）
 *  - 格式化显示（目标时间在过去）
 *  - 实时时间（无目标时间）
 *
 * @param source 可选时间源（Date | string | number），undefined 表示当前实时时间
 * @param format 格式化字符串
 *        - 若包含DDHHmmss → 视为倒计时模板
 *        - 否则视为普通格式（如 'YYYY-MM-DD'）
 * @param options 配置项
 * @returns Ref<string> 响应式时间字符串
 *
 * @example
 * const time = useTimeDisplay('2025-12-31', 'DD天HH小时mm分ss秒', {mode: 'countdown'});
 * // 实时时间
 * const now = useTimeDisplay(undefined, 'HH:mm:ss');
 */
export function useTimeDisplay(
  source?: Date | string | number,
  format: string = 'YYYY-MM-DD HH:mm:ss',
  options: UseTimeDisplayOptions = {},
) {
  const { interval = 1000, onFinish, mode = 'realtime' } = options;

  const result = ref<string>(format);
  let timer: ReturnType<typeof setInterval> | null = null;
  const { temp, p } = handleDateFormat(format, 'DHms');
  // 解析目标时间（如果 source 存在）
  let targetTime: number | null = null;

  if (source !== undefined) {
    const utils = new UseTimeUtils(source);
    targetTime = utils.valueOf();
    if (isNaN(targetTime)) {
      console.error('[useTimeDisplay] Invalid source time:', source);
      targetTime = null;
    }
  }
  // 更新函数
  const update = () => {
    const nowUtils = new UseTimeUtils();
    if (mode === 'realtime') {
      result.value = nowUtils.format(format);
    } else if (mode === 'countdown' && targetTime) {
      let remaining = targetTime - nowUtils.valueOf();
      if (remaining <= 0) {
        result.value = format.replace(/(Y|M|D|H|h|m|s|S|d)+/g, '0');
        stop();
        onFinish?.();
      } else {
        let seconds = 0;
        let minutes = 0;
        let hours = 0;
        let days = 0;
        if (format.includes('D')) {
          days = Math.floor(remaining / (1000 * 60 * 60 * 24));
          remaining = remaining % (1000 * 60 * 60 * 24);
        }
        if (format.includes('H')) {
          hours = Math.floor(remaining / (1000 * 60 * 60));
          remaining = remaining % (1000 * 60 * 60);
        }
        if (format.includes('m')) {
          minutes = Math.floor(remaining / (1000 * 60));
          remaining = remaining % (1000 * 60);
        }
        if (format.includes('s')) {
          seconds = Math.floor(remaining / 1000);
        }
        result.value = temp
          .replace('D', days.toString().padStart(p.get('D') || 0, '0'))
          .replace('H', hours.toString().padStart(p.get('H') || 0, '0'))
          .replace('m', minutes.toString().padStart(p.get('m') || 0, '0'))
          .replace('s', seconds.toString().padStart(p.get('s') || 0, '0'));
      }
    }
  };

  // 控制方法
  const start = () => {
    if (timer) return;
    update();
    timer = setInterval(update, interval);
  };

  const stop = () => {
    if (timer) {
      clearInterval(timer);
      timer = null;
    }
  };
  return {
    value: result,
    start,
    stop,
  };
}

useWindowResize.useWindowResize.ts:
/**
 * 存储所有注册的窗口尺寸变化处理器的栈
 * 每个处理器接收当前窗口的宽度和高度作为参数
 */
const resizeHandlerStack: ((width: number, height: number) => void)[] = [];

/**
 * 标记是否已绑定 window resize 事件监听器
 * 避免重复绑定
 */
let isListening = false;

/**
 * 窗口 resize 事件的统一处理函数
 * 被触发时，遍历所有注册的处理器并传入当前窗口尺寸
 */
function handleResize() {
  const width = window.innerWidth;
  const height = window.innerHeight;
  // 遍历调用所有注册的处理器
  resizeHandlerStack.forEach((handler) => handler(width, height));
}

/**
 * 组合式函数：用于监听窗口尺寸变化
 * 提供添加和移除处理器的方法，自动管理事件监听器的绑定/解绑
 */
export const useWindowResize = {
  /**
   * 添加一个窗口尺寸变化处理器
   * @param handler - 处理函数，接收 (width: number, height: number) 作为参数
   *
   * 首次调用时会自动绑定 window 的 resize 事件监听器
   */
  addHandler(handler: (width: number, height: number) => void): void {
    // 将处理器加入栈中
    resizeHandlerStack.push(handler);

    // 如果尚未监听 resize 事件，则绑定监听器
    if (!isListening) {
      window.addEventListener('resize', handleResize, { passive: true });
      isListening = true;
      // 立即触发一次，让新注册的处理器能获取当前尺寸
      handleResize();
    }
  },

  /**
   * 移除一个已注册的窗口尺寸变化处理器
   * @param handler - 要移除的处理函数（必须是原函数引用）
   *
   * 当最后一个处理器被移除时，自动解绑事件监听器，避免内存泄漏
   */
  removeHandler(handler: (width: number, height: number) => void): void {
    const index = resizeHandlerStack.indexOf(handler);
    if (index !== -1) {
      resizeHandlerStack.splice(index, 1);
    }

    // 如果没有处理器了，移除事件监听器
    if (resizeHandlerStack.length === 0 && isListening) {
      window.removeEventListener('resize', handleResize);
      isListening = false;
    }
  },

  /**
   * （可选）获取当前已注册的处理器数量，便于调试
   */
  getHandlerCount(): number {
    return resizeHandlerStack.length;
  },

  /**
   * （可选）强制触发一次 resize 事件处理（例如用于初始化或手动刷新）
   */
  triggerResize(): void {
    if (resizeHandlerStack.length > 0) {
      handleResize();
    }
  },
};

useDrag.useDrag.ts:
import { useThrottle } from '@qianrenni/core';

/**
 * @param elementRef 目标元素的引用
 * @param onMove 移动事件的回调函数（可选）
 * @param interval 节流间隔（毫秒）
 * @param threshold 移动阈值（像素）
 * @returns 返回一个包含清理方法 `destroy` 的对象, 以及是否移动的标志 `isMove`
 */
export const useDrag = (
  elementRef: HTMLElement,
  onMove?: () => void,
  interval = 16,
  threshold = 10,
) => {
  interval = interval > 16 ? interval : 16;

  let isDragging = false;
  let startX = 0;
  let startY = 0;
  let startBottom = 0;
  let startRight = 0;
  let isMove = false;
  let downTarget: EventTarget | null = null; // 记录 pointerdown 时的实际目标

  const updatePosition = (e: PointerEvent) => {
    const dx = startX - e.clientX;
    const dy = startY - e.clientY;
    elementRef.style.bottom = `${startBottom + dy}px`;
    elementRef.style.right = `${startRight + dx}px`;
    onMove?.();
  };

  const throttleDrag = useThrottle(updatePosition, interval);

  const rawDrag = (e: PointerEvent) => {
    if (!isDragging) return;

    const dx = startX - e.clientX;
    const dy = startY - e.clientY;
    const distance = Math.hypot(dx, dy);

    if (!isMove && distance >= threshold) {
      isMove = true;
    }

    throttleDrag(e);
  };

  const startDrag = (e: PointerEvent) => {
    if (e.button !== 0 && e.pointerType === 'mouse') return;

    isDragging = true;
    isMove = false;

    startX = e.clientX;
    startY = e.clientY;

    const computedStyle = getComputedStyle(elementRef);
    startBottom = parseInt(computedStyle.bottom, 10) || 0;
    startRight = parseInt(computedStyle.right, 10) || 0;

    // 记录原始点击目标（可能是子元素）
    downTarget = e.target;

    elementRef.setPointerCapture(e.pointerId);
    document.body.style.userSelect = 'none';

    elementRef.addEventListener('pointermove', rawDrag);
  };

  const stopDrag = (e: PointerEvent) => {
    if (!isDragging) return;

    const didMove = isMove;
    isDragging = false;

    try {
      elementRef.releasePointerCapture(e.pointerId);
    } catch (err) {
      console.error('Failed to release pointer capture:', err);
    }

    elementRef.removeEventListener('pointermove', rawDrag);
    document.body.style.userSelect = '';

    // 如果没有拖动，尝试恢复原始点击行为
    if (!didMove && downTarget instanceof Element) {
      // 创建一个真实的 click 事件
      const clickEvent = new MouseEvent('click', {
        bubbles: true,
        cancelable: true,
        view: window,
        detail: 1,
        button: 0,
        clientX: e.clientX,
        clientY: e.clientY,
        screenX: e.screenX,
        screenY: e.screenY,
      });

      // 在原始目标上派发 click
      downTarget.dispatchEvent(clickEvent);
    }

    // 重置 downTarget
    downTarget = null;
  };

  elementRef.addEventListener('pointerdown', startDrag);
  elementRef.addEventListener('pointerup', stopDrag);
  elementRef.addEventListener('pointercancel', stopDrag);

  return {
    destroy: () => {
      elementRef.removeEventListener('pointerdown', startDrag);
      elementRef.removeEventListener('pointerup', stopDrag);
      elementRef.removeEventListener('pointercancel', stopDrag);
      if (isDragging) {
        elementRef.removeEventListener('pointermove', rawDrag);
        try {
          elementRef.releasePointerCapture(
            (elementRef as HTMLElement & { __activePointerId?: number })
              .__activePointerId || 0,
          );
        } catch (error) {
          console.error('Failed to release pointer capture:', error);
        }
      }
      document.body.style.userSelect = '';
    },
    isMove: () => isMove,
  };
};

useFormEvents.useFormEvents.ts:
// utils/useFormEvents.ts
import { FormComponentEmits } from '@/types';

/**
 * 为表单组件创建通用事件处理器
 * @param emit defineEmits 的返回函数
 * @returns 一组预绑定 emit 的事件处理函数
 */
export function useFormEvents<T>(emit: FormComponentEmits<T>) {
  return {
    /**
     * 处理 input 事件（值变化 + emit）
     */
    handleInput(value: T) {
      emit('update:modelValue', value);
      emit('input', value);
    },

    /**
     * 处理 change 事件
     */
    handleChange(value: T) {
      emit('update:modelValue', value);
      emit('change', value);
    },

    /**
     * 处理 focus
     */
    handleFocus() {
      emit('focus');
    },

    /**
     * 处理 blur
     */
    handleBlur() {
      emit('blur');
    },

    /**
     * 处理 clear
     */
    handleClear(clearValue: T) {
      emit('update:modelValue', clearValue as T);
      emit('clear');
    },
  };
}

useMousePosition.useMousePosition.ts:
// mouse.js
import { onMounted, onUnmounted, ref } from 'vue';

// 提升状态到模块作用域（单例模式）
const x = ref(0);
const y = ref(0);
let listenerCount = 0; // 引用计数器

// 统一的事件处理器
const update = (event: MouseEvent) => {
  x.value = event.pageX;
  y.value = event.pageY;
};

/**
 * 鼠标位置跟踪钩子
 * 功能：监听鼠标移动事件，返回实时坐标 {x, y}
 * 特性：自动管理事件监听（多个组件共用时仅绑定一次事件）
 */
export const useMousePosition = () => {
  // 每当组件挂载时
  onMounted(() => {
    if (listenerCount === 0) {
      window.addEventListener('mousemove', update);
    }
    listenerCount++; // 增加引用计数
  });

  // 每当组件卸载时
  onUnmounted(() => {
    listenerCount--;
    if (listenerCount === 0) {
      window.removeEventListener('mousemove', update);
    }
  });

  // 始终返回相同的引用
  return { x, y };
};

base/base.base.css:
/**
 * Base Element Styles
 * ------------------------------------------------------------------
 * body、pre、code、滚动条等基础元素样式。
 */

:root {
  font-size: 16px;
}

body {
  text-rendering: optimizeLegibility;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  font-family: var(--q-font-family-base);
  color: var(--q-color-text);
  background-color: var(--q-color-bg);
  /* 向后兼容 */
  color: var(--text-color);
  background-color: var(--background-color);
}

/* — pre / code 滚动条 — */
pre {
  width: 100%;
  overflow: scroll;
}

pre::-webkit-scrollbar,
code::-webkit-scrollbar {
  width: 4px;
  height: 4px;
  background-color: var(--q-color-bg);
}

pre::-webkit-scrollbar-thumb,
code::-webkit-scrollbar-thumb {
  background-color: var(--q-color-primary);
}

@media screen and (max-width: 768px) {
  pre::-webkit-scrollbar {
    width: 0;
    height: 0;
  }
}

/* — 自动填充覆盖 — */
input:-webkit-autofill,
input:-webkit-autofill:hover,
input:-webkit-autofill:focus,
input:-webkit-autofill:active {
  -webkit-text-fill-color: var(--q-color-text);
  box-shadow: 0 0 0 1000px var(--q-color-bg-card) inset;
}

/* — Vue 过渡动画 — */
.fade-enter-active,
.fade-leave-active {
  transition: opacity var(--q-duration-normal) var(--q-easing-ease);
}

.fade-enter-from,
.fade-leave-to {
  opacity: 0;
}

base/reset.reset.css:
/**
 * CSS Reset
 * ------------------------------------------------------------------
 * 统一盒模型、清除默认 margin/padding、继承颜色与背景。
 * 保持与旧版 `* {}` 重置行为一致，零破坏性迁移。
 */

* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
  background-color: inherit;
  color: inherit;
}

