@import './components/badge.css';
@import './components/card.css';
@import './components/input.css';
@import './components/tag.css';
@import './components/form-table.css';
@import './components/nav-section.css';

markdown.markdown.css:
/**
 * Markdown Body Styles
 * ------------------------------------------------------------------
 * Markdown 内容排版：适配组件库主题变量与明暗模式。
 * 由 MarkdownRender 组件通过 @import 引入。
 */

.markdown-body {
  -webkit-text-size-adjust: 100%;
  color: var(--q-color-text);
  font-family: var(--q-font-family-markdown);
  font-size: 14px;
  line-height: var(--q-line-height-relaxed);
  overflow-wrap: break-word;
  word-break: normal;
}

.markdown-body > :first-child {
  margin-top: 0;
}

.markdown-body > :last-child {
  margin-bottom: 0;
}

/* 标题层级清晰，并为锚点跳转保留安全滚动距离。 */
.markdown-body h1,
.markdown-body h2,
.markdown-body h3,
.markdown-body h4,
.markdown-body h5,
.markdown-body h6 {
  margin: 32px 0 16px;
  color: var(--q-color-text);
  font-weight: var(--q-font-weight-semibold);
  line-height: 1.35;
  scroll-margin-top: 24px;
}

.markdown-body h1 {
  padding-bottom: 12px;
  font-size: 28px;
  border-bottom: 1px solid var(--q-color-border);
}

.markdown-body h2 {
  padding-bottom: 8px;
  font-size: 22px;
  border-bottom: 1px solid var(--q-color-border);
}

.markdown-body h3 {
  font-size: 18px;
}

.markdown-body h4 {
  font-size: 16px;
}

.markdown-body h5 {
  font-size: 14px;
}

.markdown-body h6 {
  color: var(--q-color-text-muted);
  font-size: 13px;
}

.markdown-body p,
.markdown-body ul,
.markdown-body ol,
.markdown-body dl,
.markdown-body blockquote,
.markdown-body pre,
.markdown-body .markdown-table-wrapper,
.markdown-body figure {
  margin: 0 0 16px;
}

.markdown-body a {
  color: var(--q-color-link);
  font-weight: var(--q-font-weight-medium);
  text-decoration: underline;
  text-decoration-color: currentColor;
  text-decoration-thickness: 1px;
  text-underline-offset: 3px;
  transition:
    color 0.2s ease,
    text-decoration-color 0.2s ease;
}

.markdown-body a:hover {
  color: var(--q-color-link-hover);
  text-decoration-color: currentColor;
}

.markdown-body a:focus-visible {
  outline: 2px solid var(--q-color-primary);
  outline-offset: 2px;
  border-radius: 2px;
}

.markdown-body strong {
  color: var(--q-color-text);
  font-weight: var(--q-font-weight-semibold);
}

.markdown-body em {
  color: var(--q-color-text-description);
}

.markdown-body del {
  color: var(--q-color-text-muted);
}

.markdown-body hr {
  height: 1px;
  margin: 24px 0;
  border: 0;
  background-color: var(--q-color-border);
  opacity: var(--q-opacity-50);
}

/* 列表支持多层嵌套与任务项。 */
.markdown-body ul,
.markdown-body ol {
  padding-left: 24px;
}

.markdown-body li + li {
  margin-top: 6px;
}

.markdown-body li > p {
  margin: 8px 0;
}

.markdown-body li > ul,
.markdown-body li > ol {
  margin: 6px 0 0;
}

.markdown-body .task-list-item {
  list-style: none;
}

.markdown-body .task-list-item input[type='checkbox'] {
  width: 14px;
  height: 14px;
  margin: 0 8px 0 -20px;
  vertical-align: -2px;
}

/* 引用、代码和键盘按键采用克制的企业文档视觉。 */
.markdown-body blockquote {
  padding: 12px 16px;
  color: var(--q-color-text-description);
  background-color: var(--q-color-gray-100);
  border-left: 4px solid var(--q-color-primary);
  border-radius: 0 4px 4px 0;
}

.markdown-body blockquote > :last-child {
  margin-bottom: 0;
}

.markdown-body code,
.markdown-body kbd {
  padding: 2px 5px;
  color: var(--q-color-text);
  font-family: var(--q-font-family-mono);
  font-size: 0.875em;
  line-height: 1.5;
  background-color: var(--q-color-gray-100);
  border: 1px solid var(--q-color-border);
  border-radius: 4px;
}

.markdown-body kbd {
  font-size: 12px;
  font-weight: var(--q-font-weight-semibold);
  box-shadow: inset 0 -1px 0 var(--q-color-gray-300);
}

.markdown-body pre {
  max-width: 100%;
  padding: 16px;
  overflow: auto;
  color: #c9d1d9;
  line-height: 1.55;
  background-color: #0d1117;
  border: 1px solid var(--q-color-border);
  border-radius: 6px;
}

.markdown-body pre code {
  display: block;
  min-width: max-content;
  padding: 0;
  color: inherit;
  font-size: 13px;
  background-color: transparent;
  border: 0;
  border-radius: 0;
}

/* 由渲染器注入容器：仅容器滚动，table 始终保留原生列宽计算。 */
.markdown-body .markdown-table-wrapper {
  width: 100%;
  overflow-x: auto;
  overscroll-behavior-x: contain;
  border: 1px solid var(--q-color-border);
  border-radius: 6px;
}

.markdown-body table {
  width: max-content;
  min-width: 100%;
  table-layout: auto;
  border-spacing: 0;
  border-collapse: separate;
}

.markdown-body th,
.markdown-body td {
  min-width: 112px;
  padding: 10px 12px;
  color: var(--q-color-text);
  text-align: left;
  vertical-align: middle;
  overflow-wrap: anywhere;
  border-right: 1px solid var(--q-color-border);
  border-bottom: 1px solid var(--q-color-border);
}

.markdown-body th {
  position: sticky;
  top: 0;
  z-index: 1;
  font-weight: var(--q-font-weight-semibold);
  white-space: nowrap;
  background-color: var(--q-color-gray-100);
}

.markdown-body tr:nth-child(even) td {
  background-color: var(--q-color-bg-secondary);
}

.markdown-body tr > :last-child {
  border-right: 0;
}

.markdown-body tr:last-child > * {
  border-bottom: 0;
}

.markdown-body .markdown-table-wrapper::-webkit-scrollbar {
  height: 6px;
}

.markdown-body .markdown-table-wrapper::-webkit-scrollbar-thumb {
  background-color: var(--q-color-gray-400);
  border-radius: var(--q-radius-full);
}

.markdown-body img {
  display: block;
  max-width: 100%;
  height: auto;
  margin: 16px auto;
  border-radius: 6px;
}

.markdown-body figure {
  text-align: center;
}

.markdown-body figcaption {
  margin-top: 8px;
  color: var(--q-color-text-muted);
  font-size: 13px;
}

.markdown-body details {
  padding: 12px 16px;
  background-color: var(--q-color-gray-100);
  border: 1px solid var(--q-color-border);
  border-radius: 6px;
}

.markdown-body summary {
  color: var(--q-color-text);
  font-weight: var(--q-font-weight-semibold);
  cursor: pointer;
}

.markdown-body details[open] summary {
  margin-bottom: 12px;
}

@media screen and (max-width: 768px) {
  .markdown-body {
    font-size: 14px;
    line-height: 1.7;
  }

  .markdown-body h1 {
    font-size: 24px;
  }

  .markdown-body h2 {
    font-size: 20px;
  }

  .markdown-body h3 {
    font-size: 17px;
  }

  .markdown-body pre {
    padding: 12px;
    border-radius: 4px;
  }

  .markdown-body .markdown-table-wrapper {
    margin-right: -4px;
    border-radius: 4px;
  }

  .markdown-body table {
    font-size: 13px;
  }

  .markdown-body th,
  .markdown-body td {
    min-width: 96px;
    padding: 8px 10px;
  }
}

theme/dark.dark.css:
/**
 * Dark Theme Overrides
 * ------------------------------------------------------------------
 * 通过 `body.dark-mode` 或 `[data-theme="dark"]` 切换暗色主题。
 * 仅覆盖语义化 token，原始调色板不变。
 */

body.dark-mode,
[data-theme='dark'] {
  /* — 品牌主色：暗色背景上提亮，增强交互反馈 — */
  --q-color-primary: var(--q-color-brown-400);
  --q-color-primary-hover: var(--q-color-brown-300);
  --q-color-primary-active: var(--q-color-brown-200);
  --q-color-primary-light: var(--q-color-brown-200);
  --q-color-primary-lighter: var(--q-color-brown-100);

  /* — 中性语义色 — */
  --q-color-text: #f0f0f0;
  --q-color-text-description: #b0b0b0;
  --q-color-text-muted: #999999;
  --q-color-text-secondary: #888888;
  --q-color-text-inverse: #ffffff;

  --q-color-bg: #121212;
  --q-color-bg-secondary: #3f3f3f;
  --q-color-bg-card: #232323;

  --q-color-border: #c5bebe;
  --q-color-border-light: #555555;

  --q-color-link: var(--q-color-brown-300);
  --q-color-link-hover: var(--q-color-brown-100);

  --q-color-tag: var(--q-color-brown-200);

  /* — 按钮 — */
  --q-color-button-bg: var(--q-color-primary);
  --q-color-button-text: #ffffff;
  --q-color-button-hover: var(--q-color-primary-hover);
  --q-color-button-disabled: #555555;

  /* — 遮罩层 — */
  --q-color-overlay: rgba(255, 255, 255, 0.2);

  /* — 阴影色 — */
  --q-color-shadow: rgba(255, 255, 255, 0.5);
  --q-color-shadow-inverse: rgba(255, 255, 255, 0.9);

  /* — 灰阶反转 — */
  --q-color-gray-50: #202020;
  --q-color-gray-100: #202020;
  --q-color-gray-200: #2a2a2a;
  --q-color-gray-300: #333333;
  --q-color-gray-400: #444444;
  --q-color-gray-500: #555555;
  --q-color-gray-600: #666666;
  --q-color-gray-700: #888888;
  --q-color-gray-800: #aaaaaa;
  --q-color-gray-900: #cccccc;

  /* — 骨架屏渐变 — */
  --q-skeleton-gradient: linear-gradient(
    90deg,
    #202020 25%,
    #101010 50%,
    #202020 75%
  );

  /* ============================================================
   * 向后兼容别名（暗色模式覆盖）
   * ========================================================== */
  --color-inverse: var(--q-color-text-inverse);
  --background-color: var(--q-color-bg);
  --secondary-background-color: var(--q-color-bg-secondary);
  --text-color: var(--q-color-text);
  --text-description: var(--q-color-text-description);
  --text-color-secondary: var(--q-color-text-secondary);
  --subtle-text-color: var(--q-color-text-muted);
  --border-color: var(--q-color-border);
  --card-bg: var(--q-color-bg-card);
  --box-shadow: var(--q-color-shadow);

  --primary-color: var(--q-color-primary);
  --primary-hover: var(--q-color-primary-hover);
  --primary-light: var(--q-color-primary-light);
  --tag-primary-color: var(--q-color-tag);

  --link-color: var(--q-color-link);
  --link-hover: var(--q-color-link-hover);

  --button-bg: var(--q-color-button-bg);
  --button-text: var(--q-color-button-text);
  --button-hover: var(--q-color-button-hover);
  --button-disabled: var(--q-color-button-disabled);

  --bg-overlay: var(--q-color-overlay);
  --shadow-inverse: var(--q-color-shadow-inverse);

  --gray-100: var(--q-color-gray-100);
  --gray-200: var(--q-color-gray-200);
  --gray-300: var(--q-color-gray-300);
  --gray-400: var(--q-color-gray-400);
  --gray-500: var(--q-color-gray-500);
  --gray-600: var(--q-color-gray-600);
  --gray-700: var(--q-color-gray-700);

  --skeleton-linear-gradient: var(--q-skeleton-gradient);
}

tokens/antd.antd.css:
/**
 * Ant Design Token 对齐层 (Semantic Aliases)
 * ------------------------------------------------------------------
 * 语义命名与 Ant Design 的设计 token 对齐（colorPrimary / colorText /
 * colorBgContainer / colorBorder / controlHeight 等），值映射到库内基础
 * 调色板与语义 token（--q-color-* / --q-font-* / --q-radius-*）。
 *
 * 前缀统一为 --q-ant-*，避免与真实 antd 运行时 CSS 变量冲突；
 * 由于取值引用的是语义 token（暗色主题会整体替换），本层无需重复定义暗色覆盖。
 *
 * 组件应优先消费本层变量（如 var(--q-ant-color-primary)），
 * 便于未来通过 ConfigProvider / 主题定制统一注入。
 */

:root {
  /* ============================================================
   * 颜色 (Color)
   * ========================================================== */

  /* — 主色 — */
  --q-ant-color-primary: var(--q-color-primary);
  --q-ant-color-primary-hover: var(--q-color-primary-hover);
  --q-ant-color-primary-active: var(--q-color-primary-active);
  --q-ant-color-primary-bg: var(--q-color-primary-lighter);

  /* — 文字 — */
  --q-ant-color-text: var(--q-color-text);
  --q-ant-color-text-secondary: var(--q-color-text-description);
  --q-ant-color-text-tertiary: var(--q-color-text-muted);
  /* 实心彩色底上的文字色 */
  --q-ant-color-text-light-solid: var(--q-color-white);
  --q-ant-color-text-dark-solid: var(--q-color-black);

  /* — 背景 — */
  --q-ant-color-bg-container: var(--q-color-bg-card);
  --q-ant-color-bg-elevated: var(--q-color-bg-card);
  --q-ant-color-bg-layout: var(--q-color-bg);
  /* 次级填充（hover / 浅底色） */
  --q-ant-color-fill-secondary: var(--q-color-bg-secondary);

  /* — 边框 — */
  --q-ant-color-border: var(--q-color-border-light);
  --q-ant-color-border-secondary: var(--q-color-border-light);

  /* — 功能色 — */
  --q-ant-color-error: var(--q-color-red-400);
  --q-ant-color-error-hover: var(--q-color-red-500);
  --q-ant-color-error-active: var(--q-color-red-600);
  --q-ant-color-error-bg: var(--q-color-red-50);
  --q-ant-color-error-border: var(--q-color-red-300);

  --q-ant-color-success: var(--q-color-green-400);
  --q-ant-color-warning: var(--q-color-orange-400);
  --q-ant-color-info: var(--q-color-blue-500);

  /* ============================================================
   * 排版 (Typography)
   * ========================================================== */

  --q-ant-font-family: var(--q-font-family-base);
  --q-ant-font-size-sm: var(--q-font-size-xs); /* 12px */
  --q-ant-font-size: var(--q-font-size-sm); /* 14px */
  --q-ant-font-size-lg: var(--q-font-size-base); /* 16px */
  --q-ant-font-weight: var(--q-font-weight-normal);

  /* ============================================================
   * 圆角 (Border Radius)
   * ========================================================== */

  --q-ant-border-radius-sm: var(--q-radius-sm);
  --q-ant-border-radius-md: var(--q-radius-md);
  --q-ant-border-radius-lg: var(--q-radius-lg);

  /* ============================================================
   * 控件高度 (Control Height)
   *   仅对齐 antd 的 SM / MD / LG 三档；按钮的 level1~6 由组件内部扩展
   * ========================================================== */

  --q-ant-control-height-sm: 1.5rem; /* 24px */
  --q-ant-control-height-md: 2rem; /* 32px */
  --q-ant-control-height-lg: 2.5rem; /* 40px */
}

tokens/color.color.css:
/**
 * Color Design Tokens
 * ------------------------------------------------------------------
 * 三层颜色架构：
 *   1. Palette  — 原始调色板（50–900），不随主题变化
 *   2. Semantic — 语义化颜色，映射 palette 到业务含义
 *   3. Alias    — 向后兼容别名，保持旧变量名可用
 *
 * 命名约定：--q-color-{role}-{shade}
 *           --q-color-{semantic-role}
 */

:root {
  /* ============================================================
   * 1. 原始调色板 (Palette)
   * ========================================================== */

  /* — 灰色 (Gray) — */
  --q-color-gray-50: #f8f9fa;
  --q-color-gray-100: #f1f1f1;
  --q-color-gray-200: #e9ecef;
  --q-color-gray-300: #dee2e6;
  --q-color-gray-400: #ced4da;
  --q-color-gray-500: #adb5bd;
  --q-color-gray-600: #868e96;
  --q-color-gray-700: #495057;
  --q-color-gray-800: #343a40;
  --q-color-gray-900: #212529;

  /* — 黄色 (Yellow / 备用) — */
  --q-color-yellow-50: #fffbeb;
  --q-color-yellow-100: #fff5cc;
  --q-color-yellow-200: #ffe680;
  --q-color-yellow-300: #ffc300;
  --q-color-yellow-400: #ffd94d;
  --q-color-yellow-500: #dca000;
  --q-color-yellow-600: #b38600;
  --q-color-yellow-700: #806100;

  /* — 褐色 (Brown / 品牌主色 · 书香) — */
  --q-color-brown-50: #fbf6ee;
  --q-color-brown-100: #f4eadd;
  --q-color-brown-200: #e8d5bc;
  --q-color-brown-300: #d4b48e;
  --q-color-brown-400: #b38a5a;
  --q-color-brown-500: #8c5a2b;
  --q-color-brown-600: #6e4521;
  --q-color-brown-700: #563619;

  /* — 红色 (Red / Danger) — */
  --q-color-red-50: #fff0f1;
  --q-color-red-100: #ffcccc;
  --q-color-red-200: #f5a3a3;
  --q-color-red-300: #e74c4c;
  --q-color-red-400: #dc3545;
  --q-color-red-500: #c82333;
  --q-color-red-600: #a71d2a;
  --q-color-red-700: #871718;

  /* — 绿色 (Green / Success) — */
  --q-color-green-50: #e6f9f0;
  --q-color-green-100: #b2f2cc;
  --q-color-green-200: #7fe0a8;
  --q-color-green-300: #4cae5f;
  --q-color-green-400: #28a745;
  --q-color-green-500: #1e8438;
  --q-color-green-600: #176b2c;
  --q-color-green-700: #0f5221;

  /* — 蓝色 (Blue / Info) — */
  --q-color-blue-50: #e8f4fd;
  --q-color-blue-100: #c8e9e5;
  --q-color-blue-200: #8fcae8;
  --q-color-blue-300: #4aa3ed;
  --q-color-blue-400: #2189e0;
  --q-color-blue-500: #0d6efd;
  --q-color-blue-600: #0a58ca;
  --q-color-blue-700: #084298;

  /* — 橙色 (Orange / Warning) — */
  --q-color-orange-50: #fff8e1;
  --q-color-orange-100: #ffeac2;
  --q-color-orange-200: #ffd180;
  --q-color-orange-300: #ffc107;
  --q-color-orange-400: #ffa000;
  --q-color-orange-500: #e69500;
  --q-color-orange-600: #b37800;

  /* — 纯黑纯白 — */
  --q-color-white: #ffffff;
  --q-color-black: #000000;

  /* ============================================================
   * 2. 语义化颜色 (Semantic)
   * ========================================================== */

  /* — 品牌主色（书香褐） — */
  --q-color-primary: var(--q-color-brown-500);
  --q-color-primary-hover: var(--q-color-brown-600);
  --q-color-primary-active: var(--q-color-brown-700);
  --q-color-primary-light: var(--q-color-brown-100);
  --q-color-primary-lighter: var(--q-color-brown-50);

  /* — 功能色 — */
  --q-color-success: var(--q-color-green-400);
  --q-color-success-bg: var(--q-color-green-50);
  --q-color-success-border: var(--q-color-green-100);

  --q-color-warning: var(--q-color-white);
  --q-color-warning-bg: var(--q-color-orange-300);
  --q-color-warning-border: var(--q-color-orange-100);

  --q-color-danger: var(--q-color-white);
  --q-color-danger-bg: var(--q-color-red-400);
  --q-color-danger-border: var(--q-color-red-100);

  --q-color-info: var(--q-color-white);
  --q-color-info-bg: var(--q-color-blue-500);
  --q-color-info-border: var(--q-color-blue-100);

  /* — 中性语义色 — */
  --q-color-text: #333333;
  --q-color-text-description: #565656;
  --q-color-text-muted: #6c757d;
  --q-color-text-secondary: #868e96;
  --q-color-text-inverse: #111111;

  --q-color-bg: var(--q-color-gray-50);
  --q-color-bg-secondary: #e8e8e8;
  --q-color-bg-card: var(--q-color-white);

  --q-color-border: #686c71;
  --q-color-border-light: var(--q-color-gray-300);

  --q-color-link: #333333;
  --q-color-link-hover: var(--q-color-primary);

  /* — 标签/标记色 — */
  --q-color-tag: var(--q-color-brown-100);

  /* — 按钮 — */
  --q-color-button-bg: var(--q-color-primary);
  --q-color-button-text: var(--q-color-white);
  --q-color-button-hover: var(--q-color-primary-hover);
  --q-color-button-disabled: var(--q-color-gray-200);

  /* — 遮罩层 — */
  --q-color-overlay: rgba(0, 0, 0, 0.5);

  /* — 阴影反色 — */
  --q-color-shadow-inverse: rgba(0, 0, 0, 0.9);

  /* ============================================================
   * 3. 向后兼容别名 (Legacy Aliases)
   *    保持旧变量名可用，内部引用新 token，零破坏性迁移。
   * ========================================================== */

  /* 纯色 */
  --color-white: var(--q-color-white);
  --color-black: var(--q-color-black);
  --color-inverse: var(--q-color-text-inverse);

  /* 背景 */
  --background-color: var(--q-color-bg);
  --secondary-background-color: var(--q-color-bg-secondary);
  --card-bg: var(--q-color-bg-card);

  /* 文字 */
  --text-color: var(--q-color-text);
  --text-description: var(--q-color-text-description);
  --text-color-secondary: var(--q-color-text-secondary);
  --subtle-text-color: var(--q-color-text-muted);

  /* 边框 */
  --border-color: var(--q-color-border);

  /* 阴影色 */
  --box-shadow: rgba(255, 255, 255, 0.5);
  --shadow-inverse: var(--q-color-shadow-inverse);

  /* 主色 */
  --primary-color: var(--q-color-primary);
  --primary-hover: var(--q-color-primary-hover);
  --primary-light: var(--q-color-primary-light);
  --tag-primary-color: var(--q-color-tag);

  /* 链接 */
  --link-color: var(--q-color-link);
  --link-hover: var(--q-color-link-hover);

  /* 功能色 */
  --success-color: var(--q-color-success);
  --success-bg: var(--q-color-success-bg);
  --success-border: var(--q-color-success-border);

  --warning-color: var(--q-color-warning);
  --warning-bg: var(--q-color-warning-bg);
  --warning-border: var(--q-color-warning-border);

  --danger-color: var(--q-color-danger);
  --danger-bg: var(--q-color-danger-bg);
  --danger-border: var(--q-color-danger-border);

  --info-color: var(--q-color-info);
  --info-bg: var(--q-color-info-bg);
  --info-border: var(--q-color-info-border);

  /* 灰阶 */
  --gray-100: var(--q-color-gray-100);
  --gray-200: var(--q-color-gray-200);
  --gray-300: var(--q-color-gray-300);
  --gray-400: var(--q-color-gray-400);
  --gray-500: var(--q-color-gray-500);
  --gray-600: var(--q-color-gray-600);
  --gray-700: var(--q-color-gray-700);

  /* 按钮 */
  --button-bg: var(--q-color-button-bg);
  --button-text: var(--q-color-button-text);
  --button-hover: var(--q-color-button-hover);
  --button-disabled: var(--q-color-button-disabled);

  /* 遮罩 */
  --bg-overlay: var(--q-color-overlay);
}

tokens/elevation.elevation.css:
/**
 * Elevation & Shadow Design Tokens
 * ------------------------------------------------------------------
 * 五级阴影体系，从扁平到浮层逐级加深。
 *
 * 命名约定：--q-shadow-{level}
 *           --q-z-index-{layer}
 */

:root {
  /* — 阴影阶梯 — */
  --q-shadow-none: none;
  --q-shadow-xs: 0 1px 2px rgba(0, 0, 0, 0.06);
  --q-shadow-sm: 0 2px 4px rgba(0, 0, 0, 0.08);
  --q-shadow-md: 0 4px 8px rgba(0, 0, 0, 0.12);
  --q-shadow-lg: 0 8px 16px rgba(0, 0, 0, 0.16);
  --q-shadow-xl: 0 16px 32px rgba(0, 0, 0, 0.2);

  /* — 阴影色（向后兼容） — */
  --q-color-shadow: rgba(255, 255, 255, 0.5);

  /* — Z-index 层级 — */
  --q-z-index-base: 1;
  --q-z-index-dropdown: 100;
  --q-z-index-sticky: 200;
  --q-z-index-fixed: 300;
  --q-z-index-overlay: 800;
  --q-z-index-modal: 1000;
  --q-z-index-popover: 9999;

  /* — 向后兼容别名 — */
  --z-index-level-1: var(--q-z-index-base);
  --z-index-level-2: var(--q-z-index-modal);
  --z-index-level-3: var(--q-z-index-popover);
}

tokens/motion.motion.css:
/**
 * Motion Design Tokens
 * ------------------------------------------------------------------
 * 动画时长、缓动函数与关键帧定义。
 *
 * 命名约定：--q-duration-{speed}
 *           --q-easing-{type}
 *           --q-transition-{property}
 */

:root {
  /* — 时长 — */
  --q-duration-instant: 0ms;
  --q-duration-fast: 150ms;
  --q-duration-normal: 300ms;
  --q-duration-slow: 500ms;
  --q-duration-slower: 800ms;

  /* — 缋动函数 — */
  --q-easing-linear: linear;
  --q-easing-ease: ease;
  --q-easing-ease-in: ease-in;
  --q-easing-ease-out: ease-out;
  --q-easing-ease-in-out: ease-in-out;

  /* — Material 风格缓动 — */
  --q-easing-standard: cubic-bezier(0.4, 0, 0.2, 1);
  --q-easing-decelerate: cubic-bezier(0, 0, 0.2, 1);
  --q-easing-accelerate: cubic-bezier(0.4, 0, 1, 1);
  --q-easing-sharp: cubic-bezier(0.4, 0, 0.6, 1);

  /* — 复合过渡 — */
  --q-transition-color: color var(--q-duration-normal)
    var(--q-easing-ease-in-out);
  --q-transition-background: background-color var(--q-duration-normal)
    var(--q-easing-ease-in-out);
  --q-transition-border: border-color var(--q-duration-normal)
    var(--q-easing-ease-in-out);
  --q-transition-opacity: opacity var(--q-duration-normal) var(--q-easing-ease);
  --q-transition-transform: transform var(--q-duration-normal)
    var(--q-easing-ease-in-out);
  --q-transition-shadow: box-shadow var(--q-duration-normal)
    var(--q-easing-ease-in-out);
  --q-transition-all: all var(--q-duration-normal) var(--q-easing-ease-in-out);

  /* — 骨架屏渐变背景 — */
  --q-skeleton-gradient: linear-gradient(
    90deg,
    var(--q-color-gray-100) 25%,
    var(--q-color-gray-200) 50%,
    var(--q-color-gray-100) 75%
  );

  /* — 向后兼容别名 — */
  --skeleton-linear-gradient: var(--q-skeleton-gradient);
}

/* — 关键帧动画（必须在 :root 外部定义） — */

/* 旋转 */
@keyframes q-rotate {
  0% {
    transform: rotate(0);
  }
  100% {
    transform: rotate(360deg);
  }
}

/* 脉冲（呼吸灯） */
@keyframes q-pulse {
  0%,
  100% {
    opacity: 1;
  }
  50% {
    opacity: 0.5;
  }
}

/* 骨架屏光泽流动 */
@keyframes q-shimmer {
  0% {
    background-position: 200% 0;
  }
  100% {
    background-position: -200% 0;
  }
}

/* 虚线路径动画 */
@keyframes q-dash {
  0% {
    stroke-dasharray: 20, 200;
    stroke-dashoffset: 0;
  }
  50% {
    stroke-dasharray: 200, 200;
    stroke-dashoffset: 100px;
  }
  100% {
    stroke-dasharray: 20, 200;
    stroke-dashoffset: 0;
  }
}

/* 卡片翻转 */
@keyframes q-up-down {
  0% {
    transform: translateY(0);
  }
  50% {
    transform: translateY(-10px) rotateY(270deg);
  }
  100% {
    transform: translateY(0) rotateY(360deg);
  }
}

/* 向上淡入 */
@keyframes q-fade-in-up {
  0% {
    opacity: 0;
    transform: translateY(8px);
  }
  100% {
    opacity: 1;
    transform: translateY(0);
  }
}

/* 向下淡入 */
@keyframes q-fade-in-down {
  0% {
    opacity: 0;
    transform: translateY(-8px);
  }
  100% {
    opacity: 1;
    transform: translateY(0);
  }
}

/* 淡入 */
@keyframes q-fade-in {
  0% {
    opacity: 0;
  }
  100% {
    opacity: 1;
  }
}

/* 淡出 */
@keyframes q-fade-out {
  0% {
    opacity: 1;
  }
  100% {
    opacity: 0;
  }
}

/* 缩放淡入 */
@keyframes q-scale-in {
  0% {
    opacity: 0;
    transform: scale(0.95);
  }
  100% {
    opacity: 1;
    transform: scale(1);
  }
}

/* — 向后兼容：旧版关键帧名称 — */
@keyframes rotate {
  0% {
    transform: rotate(0);
  }
  100% {
    transform: rotate(360deg);
  }
}

@keyframes dash {
  0% {
    stroke-dasharray: 20, 200;
    stroke-dashoffset: 0;
  }
  50% {
    stroke-dasharray: 200, 200;
    stroke-dashoffset: 100px;
  }
  100% {
    stroke-dasharray: 20, 200;
    stroke-dashoffset: 0;
  }
}

@keyframes pulse {
  0%,
  100% {
    opacity: 1;
  }
  50% {
    opacity: 0.5;
  }
}

@keyframes shimmer {
  0% {
    background-position: 200% 0;
  }
  100% {
    background-position: -200% 0;
  }
}

@keyframes up-down {
  0% {
    transform: translateY(0);
  }
  50% {
    transform: translateY(-10px) rotateY(270deg);
  }
  100% {
    transform: translateY(0) rotateY(360deg);
  }
}

tokens/spacing.spacing.css:
/**
 * Spacing Design Tokens
 * ------------------------------------------------------------------
 * 基于 4px 基础单位的间距阶梯，共 12 档（0 → 48px）。
 *
 * 命名约定：--q-space-{n}     → 通用间距
 *           --q-space-{n}x    → 行列间距（gap）
 *
 * 向后兼容别名保留旧的 --distance / --half-distance 等。
 */

:root {
  /* — 间距阶梯 (4px base) — */
  --q-space-0: 0;
  --q-space-1: 0.125rem; /* 2px */
  --q-space-2: 0.25rem; /* 4px */
  --q-space-3: 0.375rem; /* 6px */
  --q-space-4: 0.5rem; /* 8px */
  --q-space-5: 0.75rem; /* 12px */
  --q-space-6: 1rem; /* 16px */
  --q-space-7: 1.25rem; /* 20px */
  --q-space-8: 1.5rem; /* 24px */
  --q-space-9: 2rem; /* 32px */
  --q-space-10: 2.5rem; /* 40px */
  --q-space-11: 3rem; /* 48px */
  --q-space-12: 4rem; /* 64px */

  /* — 向后兼容别名 — */
  --distance: var(--q-space-6);
  --half-distance: var(--q-space-4);
  --third-distance: var(--q-space-3);
  --fourth-distance: var(--q-space-2);
}

tokens/typography.typography.css:
/**
 * Typography Design Tokens
 * ------------------------------------------------------------------
 * 字体族、字号、字重、行高与排版阶梯。
 *
 * 命名约定：--q-font-{property}-{value}
 */

:root {
  /* — 字体族 — */
  --q-font-family-base:
    -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, 'Helvetica Neue',
    Arial, sans-serif, 'Apple Color Emoji', 'Segoe UI Emoji';
  --q-font-family-mono:
    'SFMono-Regular', Consolas, 'Liberation Mono', Menlo, monospace;
  --q-font-family-markdown:
    -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, 'Helvetica Neue',
    Arial, sans-serif, 'Apple Color Emoji', 'Segoe UI Emoji';

  /* — 基础字号 — */
  --q-font-size-base: 1rem; /* 16px */
  --q-font-size-sm: 0.875rem; /* 14px */
  --q-font-size-xs: 0.75rem; /* 12px */
  --q-font-size-lg: 1.125rem; /* 18px */
  --q-font-size-xl: 1.25rem; /* 20px */
  --q-font-size-2xl: 1.5rem; /* 24px */
  --q-font-size-3xl: 2rem; /* 32px */

  /* — 文字阶梯（旧版 rem 简写） — */
  --q-font-size-03: 0.3rem;
  --q-font-size-05: 0.5rem;
  --q-font-size-08: 0.8rem;
  --q-font-size-085: 0.85rem;
  --q-font-size-12: 1.2rem;
  --q-font-size-15: 1.5rem;
  --q-font-size-2: 2rem;

  /* — 字重 — */
  --q-font-weight-light: 300;
  --q-font-weight-normal: 400;
  --q-font-weight-medium: 500;
  --q-font-weight-semibold: 600;
  --q-font-weight-bold: 700;

  /* — 行高 — */
  --q-line-height-tight: 1.2;
  --q-line-height-normal: 1.5;
  --q-line-height-relaxed: 1.75;

  /* — 字间距 — */
  --q-letter-spacing-normal: normal;
  --q-letter-spacing-wide: 0.025em;
  --q-letter-spacing-wider: 0.05em;
}

