utilities/display.display.css:
/**
 * Display, Position & Visibility Utilities
 * ------------------------------------------------------------------
 * display、position、cursor、opacity、border、radius 等工具类。
 * 同时保留旧版类名。
 */

/* ============================================================
 * Display
 * ========================================================== */

.d-none {
  display: none;
}

.d-block {
  display: block;
}

.d-inline {
  display: inline;
}

.d-inline-block {
  display: inline-block;
}

.d-flex {
