}

.col-span-full {
  grid-column: 1 / -1;
}

/* ============================================================
 * 向后兼容：旧版 container / inner-container 类名
 * ========================================================== */

.inner-container {
  display: flex;
  gap: var(--q-space-2);
  align-items: center;
}

.inner-container-column {
  display: flex;
  flex-direction: column;
