/**
 * Typography Utilities — Font Size, Weight, Align, Truncation
 * ------------------------------------------------------------------
 * 文字排版工具类。
 *
 * 格式：.text-{align}            对齐
 *       .text-{size}             字号
 *       .font-{weight}           字重
 *       .text-{n}-line           截断行数
 *
 * 同时保留旧版类名。
 */

/* ============================================================
 * 对齐
 * ========================================================== */

.text-left {
  text-align: left;
}

.text-center {
  text-align: center;
}

.text-right {
  text-align: right;
}

.text-justify {
  text-align: justify;
}

/* ============================================================
 * 字号
 * ========================================================== */

.text-xs {
  font-size: var(--q-font-size-xs);
}

.text-sm {
  font-size: var(--q-font-size-sm);
}

.text-base {
  font-size: var(--q-font-size-base);
}

.text-lg {
  font-size: var(--q-font-size-lg);
}

.text-xl {
  font-size: var(--q-font-size-xl);
}

.text-2xl {
  font-size: var(--q-font-size-2xl);
}

.text-3xl {
  font-size: var(--q-font-size-3xl);
}

/* ============================================================
 * 字重
 * ========================================================== */

.font-light {
  font-weight: var(--q-font-weight-light);
}

.font-normal {
  font-weight: var(--q-font-weight-normal);
}

.font-medium {
  font-weight: var(--q-font-weight-medium);
}

.font-semibold {
  font-weight: var(--q-font-weight-semibold);
}

.font-bold {
  font-weight: var(--q-font-weight-bold);
}

/* ============================================================
 * 文字截断
 * ========================================================== */

.text-nowrap {
  white-space: nowrap;
}

.text-one-line {
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  -webkit-line-clamp: 1;
  line-clamp: 1;
  -webkit-box-orient: vertical;
}

.text-overflow {
  overflow: hidden;
  text-overflow: ellipsis;
}

.text-two-line {
  white-space: wrap;
  overflow: hidden;
  text-overflow: ellipsis;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  line-clamp: 2;
  -webkit-box-orient: vertical;
}

.text-tree-line {
  white-space: wrap;
  line-clamp: 3;
  overflow: hidden;
  text-overflow: ellipsis;
  -webkit-line-clamp: 3;
  -webkit-box-orient: vertical;
}

.text-3-line {
  white-space: wrap;
  overflow: hidden;
  text-overflow: ellipsis;
  display: -webkit-box;
  -webkit-line-clamp: 3;
  line-clamp: 3;
  -webkit-box-orient: vertical;
}

/* ============================================================
 * 排版辅助
 * ========================================================== */

.text-title {
  font-size: var(--q-font-size-12);
  font-weight: var(--q-font-weight-medium);
  line-height: var(--q-line-height-tight);
}

.text-label {
  font-size: var(--q-font-size-085);
  padding: var(--q-space-1);
}

/* — 用户选择 — */
.user-select-none {
